insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-01', 'k-geometry', 1, 'قصّ طالب ورقة مربعة طول ضلعها 8 سم ليغطي بها سطحاً. ما مساحة الورقة بالسنتيمتر المربع؟', '["16","32","64","72"]'::jsonb, 2, 'مساحة المربع = الضلع × نفسه = 8 × 8 = 64 سم².') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-02', 'k-geometry', 1, 'أراد طالب تزيين إطار لوحة مربعة طول ضلعها 7 سم بشريط لاصق يحيط بها كاملة. كم سنتيمتراً من الشريط يحتاج؟', '["14","21","28","49"]'::jsonb, 2, 'المطلوب المحيط لا المساحة: محيط المربع = 4 × 7 = 28 سم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-03', 'k-geometry', 2, 'حُددت في ملعب المدرسة منطقة مستطيلة للعب طولها 25 متراً وعرضها 16 متراً. ما مساحة هذه المنطقة؟', '["41 م²","82 م²","400 م²","500 م²"]'::jsonb, 2, 'مساحة المستطيل = الطول × العرض = 25 × 16 = 400 م². (لو طُلب السياج حولها لكان المحيط 82 م).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-04', 'k-geometry', 2, 'يمشي خالد يومياً حول حديقة مستطيلة طولها 30 متراً وعرضها 20 متراً دورة واحدة. كم متراً يقطع في 3 أيام؟', '["100","150","300","600"]'::jsonb, 2, 'المحيط = 2 × (30 + 20) = 100 متر يومياً، وفي 3 أيام = 300 متر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-05', 'k-geometry', 2, 'قصّت معلمة قطعة ورقية مثلثة قاعدتها 10 سم وارتفاعها العمودي 6 سم. ما مساحتها؟', '["16 سم²","30 سم²","32 سم²","60 سم²"]'::jsonb, 1, 'مساحة المثلث = ½ × القاعدة × الارتفاع = ½ × 10 × 6 = 30 سم².') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-06', 'k-geometry', 3, 'مثلث مساحته 36 سم² وقاعدته 9 سم. ما ارتفاعه العمودي على هذه القاعدة؟', '["4 سم","6 سم","8 سم","12 سم"]'::jsonb, 2, 'الارتفاع = (المساحة × 2) ÷ القاعدة = 72 ÷ 9 = 8 سم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-07', 'k-geometry', 2, 'صمم طالب مجسم طائرة ورقية على شكل معين قطراه 12 سم و8 سم. ما مساحته؟', '["40 سم²","48 سم²","96 سم²","20 سم²"]'::jsonb, 1, 'مساحة المعين = ½ × حاصل ضرب القطرين = ½ × 12 × 8 = 48 سم².') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-08', 'k-geometry', 2, 'رسمت طالبة دائرة نصف قطرها 7 سم. ما مساحتها التقريبية؟ (π ≈ 22/7)', '["44 سم²","98 سم²","154 سم²","308 سم²"]'::jsonb, 2, 'مساحة الدائرة = π × نق² = (22/7) × 49 = 154 سم².') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-09', 'k-geometry', 2, 'أراد مزارع إحاطة مزرعته الدائرية التي قطرها 14 متراً بسياج. ما طول السياج تقريباً؟ (π ≈ 22/7)', '["22 متراً","44 متراً","88 متراً","154 متراً"]'::jsonb, 1, 'محيط الدائرة = π × القطر = (22/7) × 14 = 44 متراً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-10', 'k-geometry', 3, 'أحاط رجل حديقته الدائرية بسياج طوله 88 متراً. ما طول قطر الحديقة تقريباً؟ (π ≈ 22/7)', '["14 متراً","21 متراً","28 متراً","44 متراً"]'::jsonb, 2, 'القطر = المحيط ÷ π = 88 ÷ (22/7) = 88 × 7 ÷ 22 = 28 متراً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-11', 'k-geometry', 2, 'صنعت طالبة صندوقاً مكعب الشكل طول ضلعه 3 سم وأرادت تغليفه من جميع جوانبه بورق ملون. كم سنتيمتراً مربعاً تحتاج؟', '["27 سم²","36 سم²","54 سم²","9 سم²"]'::jsonb, 2, 'مساحة سطح المكعب = 6 × الضلع² = 6 × 9 = 54 سم². (الحجم 27 سم³ إجابة مموهة).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-12', 'k-geometry', 1, 'ما حجم مكعب طول ضلعه 4 سم؟', '["12 سم³","16 سم³","48 سم³","64 سم³"]'::jsonb, 3, 'حجم المكعب = الضلع³ = 4 × 4 × 4 = 64 سم³.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-13', 'k-geometry', 3, 'خزان على شكل مكعب حجمه 125 متراً مكعباً. ما طول ضلعه؟', '["5 أمتار","11 متراً","15 متراً","25 متراً"]'::jsonb, 0, 'الضلع = الجذر التكعيبي للحجم = ∛125 = 5 أمتار (لأن 5³ = 125).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-14', 'k-geometry', 3, 'صمم طالب مجسماً هرمياً قاعدته مربعة طول ضلعها 6 سم وارتفاعه العمودي 5 سم. ما حجمه؟', '["30 سم³","60 سم³","90 سم³","180 سم³"]'::jsonb, 1, 'حجم الهرم = ⅓ × مساحة القاعدة × الارتفاع = ⅓ × 36 × 5 = 60 سم³.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-15', 'k-geometry', 3, 'يدور عداء حول ميدان مربع الشكل محيطه 1.2 كم. إذا قطع في تدريبه 4.2 كم، فكم دورة تقريباً أكمل؟', '["دورتان ونصف","3 دورات","3 دورات ونصف","4 دورات"]'::jsonb, 2, 'عدد الدورات = 4.2 ÷ 1.2 = 3.5 دورة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kg-16', 'k-geometry', 3, 'أسطوانة مساحة قاعدتها 20 سم² وارتفاعها 9 سم. ما حجمها؟', '["90 سم³","180 سم³","29 سم³","60 سم³"]'::jsonb, 1, 'حجم الأسطوانة = مساحة القاعدة × الارتفاع = 20 × 9 = 180 سم³.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-01', 'k-units', 1, 'صفّ عامل 80 بلاطة طول كل منها 25 سم بجانب بعضها في خط مستقيم. ما طول الصف بالمتر؟', '["20 متراً","25 متراً","200 متر","2000 متر"]'::jsonb, 0, '80 × 25 = 2000 سم، وبالقسمة على 100: 2000 ÷ 100 = 20 متراً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
