insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-03', 'k-units', 2, 'يطلي عامل أنبوباً طوله 3600 متر مقابل 40 ريالاً لكل كيلومتر. كم ريالاً يتقاضى عند إنهائه كاملاً؟', '["120","144","150","160"]'::jsonb, 1, '3600 م = 3.6 كم، والأجر = 3.6 × 40 = 144 ريالاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-04', 'k-units', 1, 'تستهلك أسرة 2500 جرام من الأرز يومياً. كم كيلوجراماً تستهلك خلال 4 أيام؟', '["10","100","1000","25"]'::jsonb, 0, '2500 × 4 = 10000 جم = 10 كجم (÷1000).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-05', 'k-units', 2, 'اشترى رجل 250 جراماً من الهيل بمبلغ 30 ريالاً. كم سعر الكيلوجرام الواحد؟', '["90 ريالاً","100 ريال","120 ريالاً","150 ريالاً"]'::jsonb, 2, 'الكيلوجرام = 4 × 250 جم، فالسعر = 30 × 4 = 120 ريالاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-06', 'k-units', 2, 'في وصفة جماعية استخدمت طاهية: 750 جم دقيقاً، و0.5 كجم سكراً، و500 جم زبدة، و250 جم مكسرات. ما الكتلة الكلية بالكيلوجرام؟', '["1.5","2","2.5","3"]'::jsonb, 1, '750 + 500 + 500 + 250 = 2000 جم = 2 كجم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-07', 'k-units', 1, 'ملأت طالبة 4 زجاجات سعة كل منها نصف لتر بالعصير. ما كمية العصير بالمليلتر؟', '["1000","1500","2000","4000"]'::jsonb, 2, '4 × 0.5 = 2 لتر = 2000 مل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-08', 'k-units', 2, 'يشرب رياضي 750 مليلتراً من الماء بعد كل تمرين. إذا تمرن 8 مرات في الأسبوع، فكم لتراً يشرب بعد التمارين أسبوعياً؟', '["4","5","6","8"]'::jsonb, 2, '750 × 8 = 6000 مل = 6 لترات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-09', 'k-units', 2, 'ركّب عامل سياجاً حول حديقة مربعة طول ضلعها 15 ياردة. ما الطول الكلي للسياج بوحدة القدم؟', '["45","60","180","135"]'::jsonb, 2, 'المحيط = 4 × 15 = 60 ياردة، والياردة = 3 أقدام، فالطول = 60 × 3 = 180 قدماً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
