insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-11', 'k-units', 3, 'يخزن تاجر عصيراً في براميل سعة كل منها 5 جالونات، ويعبئه في عبوات سعة كل منها كوارت واحد. كم عبوة يملأ من البرميل الواحد؟ (الجالون = 4 كوارتات)', '["9","16","20","24"]'::jsonb, 2, '5 × 4 = 20 كوارتاً = 20 عبوة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ku-12', 'k-units', 2, 'استغرقت رحلة مدرسية ساعتين وثلث الساعة. كم دقيقة استغرقت الرحلة؟', '["130","135","140","150"]'::jsonb, 2, 'ساعتان = 120 دقيقة + ثلث الساعة = 20 دقيقة، فالمجموع 140 دقيقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-01', 'k-stats', 1, 'يُعد عدد الكتب التي استعارها كل طالب من المكتبة متغيراً:', '["وصفياً","كمياً منفصلاً","كمياً متصلاً","اسمياً"]'::jsonb, 1, 'عدد الكتب قيم صحيحة لا تقبل الكسور، فهو كمي منفصل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-02', 'k-stats', 1, 'طلبت معلمة من طالباتها تحديد لونهن المفضل (أحمر، أزرق، أخضر). ما مستوى القياس المستخدم؟', '["اسمي","رتبي","فئوي","نسبي"]'::jsonb, 0, 'الألوان تصنيف وصفي بلا ترتيب، فالمقياس اسمي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-03', 'k-stats', 2, 'في استبانة، حدد الطلاب نوع النشاط الذي شاركوا فيه (علمي، ثقافي، رياضي)، ثم تقديرهم النهائي (ممتاز، جيد جداً، جيد). ما مستويا القياس على التوالي؟', '["اسمي ثم رتبي","رتبي ثم اسمي","اسمي ثم نسبي","فئوي ثم رتبي"]'::jsonb, 0, 'نوع النشاط تصنيف بلا ترتيب (اسمي)، والتقديرات تصنيف مرتب (رتبي).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-04', 'k-stats', 3, 'كل ما يلي يقاس بالمقياس النسبي ما عدا:', '["وزن الطالب","عدد أيام الغياب","طول الطالب","درجة الحرارة المئوية"]'::jsonb, 3, 'درجة الحرارة المئوية ليس لها صفر حقيقي (الصفر لا يعني انعدام الحرارة)، فهي مقياس فئوي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-05', 'k-stats', 1, 'أراد معلم تمثيل نسبة كل مصدر من مصادر دخل مشروع صفي إلى المجموع الكلي. ما التمثيل الأنسب؟', '["الأعمدة","الخطوط","القطاعات الدائرية","المدرج التكراري"]'::jsonb, 2, 'القطاعات الدائرية هي الأنسب لمقارنة جزء بالنسبة إلى الكل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-06', 'k-stats', 1, 'أرادت معلمة إبراز الفروق في عدد الكتب المقروءة بين خمسة صفوف خلال شهر. ما التمثيل الأنسب؟', '["القطاعات الدائرية","الأعمدة البيانية","المنحنى التكراري","أشكال فن"]'::jsonb, 1, 'الأعمدة تناسب مقارنة الأعداد بين فئات منفصلة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-07', 'k-stats', 1, 'أراد معلم عرض تغير درجات حرارة مختبر العلوم على مدار أسبوع. ما التمثيل الأنسب؟', '["الأعمدة","القطاعات الدائرية","الخط البياني","النقاط"]'::jsonb, 2, 'الخطوط تُظهر التغير المستمر عبر الزمن وتساعد على التنبؤ.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-08', 'k-stats', 2, 'صنّف معلم درجات طلابه في فئات متساوية (0–10، 11–20، ...) وسجل عدد الطلاب في كل فئة. ما الشكل الأنسب لعرض هذه البيانات؟', '["المدرج التكراري","القطاعات الدائرية","أشكال فن","النقاط"]'::jsonb, 0, 'المدرج التكراري يعرض توزيع بيانات كمية مبوبة في فئات بأعمدة متلاصقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-09', 'k-stats', 2, 'أراد معلم معرفة عدد الطالبات الحاصلات على أقل من 50 درجة اعتماداً على الفئات المتدرجة. ما الشكل الأنسب؟', '["الأعمدة المنفصلة","المنحنى التكراري المتجمع الصاعد","القطاعات الدائرية","التمثيل بالنقاط"]'::jsonb, 1, 'المنحنى المتجمع الصاعد يُظهر عدد القيم التي تقل عن حد معين.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-10', 'k-stats', 3, 'إذا كان في توزيع درجات اختبار: المتوسط = 45، والوسيط = 55، والمنوال = 65، فإن التوزيع:', '["ملتوٍ التواءً موجباً والاختبار صعب","ملتوٍ التواءً سالباً وأداء الطلاب مرتفع","اعتدالي وأداء الطلاب متوسط","ملتوٍ التواءً موجباً وأداء الطلاب مرتفع"]'::jsonb, 1, 'عندما يكون المتوسط < الوسيط < المنوال يكون الالتواء سالباً، ومعناه أن أغلب الدرجات مرتفعة (اختبار سهل).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-11', 'k-stats', 3, 'أظهر منحنى توزيع درجات اختبارٍ التواءً موجباً واضحاً. ما التفسير التربوي الأدق؟', '["أغلب الطلاب حصلوا على درجات مرتفعة","الاختبار كان صعباً وأغلب الدرجات منخفضة","الدرجات موزعة توزيعاً اعتدالياً","نصف الطلاب فوق المتوسط تماماً"]'::jsonb, 1, 'الالتواء الموجب: تتركز الدرجات في الطرف المنخفض ويمتد الذيل نحو الدرجات العالية القليلة، أي أن الاختبار صعب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ks-12', 'k-stats', 2, 'في التوزيع الاعتدالي (الطبيعي) تكون العلاقة بين المقاييس:', '["المتوسط > الوسيط > المنوال","المتوسط < الوسيط < المنوال","المتوسط = الوسيط = المنوال","المنوال = ضعف الوسيط"]'::jsonb, 2, 'التوزيع الاعتدالي متماثل، وتتساوى فيه مقاييس النزعة المركزية الثلاثة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-01', 'k-central', 1, 'الدرجات الآتية لعدد من الطلاب: 5، 8، 7، 5، 9، 5، 6. ما المنوال؟', '["5","6","7","9"]'::jsonb, 0, 'المنوال هو القيمة الأكثر تكراراً، و5 تكررت ثلاث مرات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-02', 'k-central', 2, 'أظهر توزيع درجات اختبارٍ أنه ثنائي المنوال. ما الاستنتاج التربوي الأدق؟', '["معظم الدرجات قريبة من المتوسط","وجود مجموعتين متباينتين في مستوى التحصيل","نصف الطلاب فوق المتوسط","التوزيع اعتدالي تماماً"]'::jsonb, 1, 'وجود قمتين للتكرار يدل غالباً على مجموعتين مختلفتين في المستوى (متمكنون ومتعثرون).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-03', 'k-central', 2, 'أي العبارات الآتية لا تُعد من خصائص المنوال؟', '["يمكن إيجاده للبيانات الاسمية","قد يتعدد في مجموعة واحدة","قد لا يوجد في بعض البيانات","يتأثر كثيراً بالقيم المتطرفة"]'::jsonb, 3, 'المنوال لا يتأثر بالقيم المتطرفة لأنه يعتمد على التكرار فقط، وهذا ما يميزه عن المتوسط.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-04', 'k-central', 1, 'حصلت طالبة في خمسة اختبارات قصيرة على الدرجات: 8، 6، 9، 7، 10. ما المتوسط الحسابي لدرجاتها؟', '["7","7.5","8","8.5"]'::jsonb, 2, 'المجموع = 40 ÷ 5 = 8.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
